#ifndef CALC_H
#define CALC_H

int add(int x, int y);
int subtract(int x, int y);

#endif

#include "calc.h"

int add(int x, int y) {
  return x + y;
}

int subtract(int x, int y) {
  return x - y;
}

#include <stdio.h>
#include "calc.h"

int main() {
  printf("5 + 5 = %d\n", add(5, 5));
  printf("6 - 4 = %d\n", subtract(6, 4));
  return 0;
}
